style.css:
@-moz-document domain("roblox.com") {
/* Target the play button on game pages */
    .game-home-page .game-buttons .btn-common-play,
    .game-home-page .game-buttons .btn-primary-play {
        background-color: yellow !important;
        border-color: #d4af37 !important;
        color: black !important;
    }
    
    /* Hover effect */
    .game-home-page .game-buttons .btn-common-play:hover,
    .game-home-page .game-buttons .btn-primary-play:hover {
        background-color: gold !important;
        border-color: #b8860b !important;
    }
}
